-- Spot catalog seed: adds region/description/featured columns and upserts the
-- full set of surf breaks. Idempotent: keyed on a unique index over name, so
-- re-running updates existing rows (and keeps their ids / favorites intact).
ALTER TABLE spots ADD COLUMN IF NOT EXISTS region TEXT;
ALTER TABLE spots ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE spots ADD COLUMN IF NOT EXISTS featured BOOLEAN NOT NULL DEFAULT false;
CREATE UNIQUE INDEX IF NOT EXISTS spots_name_uidx ON spots (name);

ON CONFLICT (name) DO UPDATE SET
  lat = EXCLUDED.lat,
  lon = EXCLUDED.lon,
  region = EXCLUDED.region,
  description = EXCLUDED.description,
  featured = EXCLUDED.featured;
